    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
    String usuario = jTextField1.getText().trim();
    String contrasena = jTextField2.getText().trim();

    if (usuario.isEmpty() || contrasena.isEmpty() || usuario.equals("Escriba su usuario...")) {
        javax.swing.JOptionPane.showMessageDialog(this, "Debe ingresar un usuario y una contraseña.");
        return;
    }

    GestorEjercicios gestorCompartido = new GestorEjercicios();

    //Valida si el usuario y la contraseña son exactos
    if (gestorCompartido.validarUsuario(usuario, contrasena)) {
        javax.swing.JOptionPane.showMessageDialog(this, "¡Inicio de sesión exitoso!");
        
        // Abre el menú principal y cierra el login
        GUI.Principal menuPrincipal = new GUI.Principal(gestorCompartido);
        menuPrincipal.setVisible(true);
        this.dispose();
        
    } else {
        //Si falló, revisamos si el usuario al menos ya existe en el archivo .dat
        if (gestorCompartido.existeUsuario(usuario)) {
            //El usuario SÍ existe, por lo tanto lo que puso mal fue la contraseña
            javax.swing.JOptionPane.showMessageDialog(this, 
                "Contraseña incorrecta. Inténtelo de nuevo.", 
                "Error de Acceso", 
                javax.swing.JOptionPane.ERROR_MESSAGE);
        } else {
            //El usuario NO existe en absoluto, aquí SÍ preguntamos si desea registrarlo
            int respuesta = javax.swing.JOptionPane.showConfirmDialog(this, 
                "El usuario no existe.\n¿Desea registrarse con este nuevo usuario?", 
                "Registrar Usuario", javax.swing.JOptionPane.YES_NO_OPTION);
                
            if (respuesta == javax.swing.JOptionPane.YES_OPTION) {
                boolean registrado = gestorCompartido.registrarUsuario(usuario, contrasena);
                if (registrado) {
                    javax.swing.JOptionPane.showMessageDialog(this, "¡Usuario registrado y guardado con éxito! Bienvenido.");
                    
                    //Abre el menú principal directo
                    GUI.Principal menuPrincipal = new GUI.Principal(gestorCompartido);
                    menuPrincipal.setVisible(true);
                    this.dispose();
                } else {
                    javax.swing.JOptionPane.showMessageDialog(this, "Error: No se pudo registrar el usuario.");
                }
            }
        }
    }
    
    }//GEN-LAST:event_jButton1ActionPerformed

